 ['Singly Linked List - Treasure Hunt','Singly','An automatic treasure hunt demonstrating singly linked-list operations.','singly_linked_list.pdf'],
 ['Doubly Linked List - Music Playlist','Doubly','A functional music playlist demonstrating doubly linked-list operations.','doubly_linked_list.pdf'],
 ['Circular Linked List - Hot Potato','Circular','An automatic Hot Potato game demonstrating circular linked-list operations.','circular_linked_list.pdf']
];
foreach($customSeeds as $cs){ $q=$pdo->prepare('SELECT id FROM activities WHERE title=? LIMIT 1'); $q->execute([$cs[0]]); if(!$q->fetch()){ $ins=$pdo->prepare('INSERT INTO activities(title,type,description,code,input_hint,reference_pdf) VALUES(?,?,?,?,?,?)'); $ins->execute([$cs[0],$cs[1],$cs[2],'','',''.$cs[3]]); } }
$game = $_GET['game'] ?? '';
$id=(int)($_GET['id'] ?? 0);
if (in_array($game,['singly','doubly','circular'],true)) {
  $map=['singly'=>'Singly Linked List - Treasure Hunt','doubly'=>'Doubly Linked List - Music Playlist','circular'=>'Circular Linked List - Hot Potato'];
  $qg=$pdo->prepare('SELECT * FROM activities WHERE title=? LIMIT 1'); $qg->execute([$map[$game]]); $a=$qg->fetch();
} else {
$stmt=$pdo->prepare("SELECT * FROM activities WHERE id=?"); $stmt->execute([$id]); $a=$stmt->fetch();
}
if(!$a){ http_response_code(404); die("Activity not found."); }
