<section class="panel" style="margin-top:18px"><div class="panel-title"><h2>Required Operations</h2><span>Linked-list practice</span></div><p>Insert at Beginning · Insert at End · Insert at Given Position · Delete at Beginning · Delete at End · Delete at Given Position · Undo Last Change</p><?php if(!empty($a['reference_pdf'])): ?><a class="btn" target="_blank" href="resources/<?= htmlspecialchars($a['reference_pdf']) ?>">Open Reference PDF</a><?php endif; ?></section></main>
<script>
(function(){const $=id=>document.getElementById(id); function pos(v,max){let n=parseInt(v,10);return Number.isFinite(n)?Math.max(1,Math.min(n,max)):0}
function stack(){return []}
// SINGLY
if($('singlyGame')){let a=['Map','Forest','Bridge','Cave','Treasure'], hist=[], timer=null, idx=-1; const save=()=>hist.push(a.slice()); const render=()=>{$('sNodes').innerHTML='';a.forEach((v,i)=>{$('sNodes').insertAdjacentHTML('beforeend',(i?' <span class="arrow">→</span> ':'')+'<div class="node '+(i===idx?'current ':'')+(v==='Treasure'?'treasure':'')+'"><strong>'+esc(v)+'</strong><small>node '+(i+1)+'</small></div>')});}; const msg=t=>$('sMsg').textContent=t; const winner=()=>{const w=$('sWinner');w.style.display='block';w.textContent='🏆 WINNER: THE EXPLORER! Treasure found!';}; const hideWinner=()=>{$('sWinner').style.display='none';}; const mutate=(fn)=>{save();fn();idx=Math.min(idx,a.length-1);hideWinner();render()}; const add=()=>{let n=$('sName').value.trim();if(!n)return msg('Enter a node/location name.');return n}; $('sAddB').onclick=()=>{let n=add();if(n)mutate(()=>a.unshift(n))}; $('sAddE').onclick=()=>{let n=add();if(n)mutate(()=>a.push(n))}; $('sAddP').onclick=()=>{let n=add(),p=pos($('sPos').value,a.length+1);if(n&&p)mutate(()=>a.splice(p-1,0,n))}; $('sDelB').onclick=()=>{if(!a.length)return;mutate(()=>a.shift());msg('Deleted the first node.')}; $('sDelE').onclick=()=>{if(!a.length)return;mutate(()=>a.pop());msg('Deleted the last node.')}; $('sDelP').onclick=()=>{let p=pos($('sPos').value,a.length);if(!p)return msg('Enter a valid position.');mutate(()=>a.splice(p-1,1))}; $('sUndo').onclick=()=>{if(hist.length){a=hist.pop();idx=-1;hideWinner();render();msg('Last change undone.')}}; $('sReset').onclick=()=>{clearInterval(timer);timer=null;a=['Map','Forest','Bridge','Cave','Treasure'];hist=[];idx=-1;hideWinner();render();msg('Game reset.')}; $('sStart').onclick=()=>{if(a.length<1)return;clearInterval(timer);hideWinner();idx=0;render();msg('Treasure hunt started!');timer=setInterval(()=>{idx++;render();if(idx>=a.length-1){clearInterval(timer);timer=null;msg('Treasure reached!');winner();}},1200)}; $('sPause').onclick=()=>{clearInterval(timer);timer=null;msg('Treasure hunt paused.');}; render();}
// DOUBLY
if($('doublyGame')){let a=[{t:'Song One',ar:'Demo',src:null},{t:'Song Two',ar:'Demo',src:null}],hist=[],cur=0,db=null; const save=()=>hist.push(a.map(x=>({...x,src:null}))); const esc2=esc; const render=()=>{$('dNodes').innerHTML='';a.forEach((x,i)=>{$('dNodes').insertAdjacentHTML('beforeend',(i?' <span class="arrow">↔</span> ':'')+'<div class="node '+(i===cur?'current':'')+'"><strong>'+esc2(x.t)+'</strong><small>'+esc2(x.ar)+'<br><button class="btn" data-play="'+i+'">▶</button></small></div>')});document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>play(+b.dataset.play));}; const msg=t=>$('dMsg').textContent=t; function play(i){if(!a[i].src)return msg('This song has no uploaded audio file. Add an MP3/MP4/audio file.');cur=i;$('dAudio').src=a[i].src;$('dAudio').play().catch(()=>{});render();msg('Playing: '+a[i].t)} $('dAudio').onended=()=>{if(a.length){cur=(cur+1)%a.length;play(cur)}}; function add(){let t=$('dTitle').value.trim(),ar=$('dArtist').value.trim(),f=$('dFile').files[0];if(!t||!ar)return msg('Enter song title and artist.');if(!f)return msg('Choose an audio file first.');return {t,ar,src:URL.createObjectURL(f)}}; const mutate=fn=>{save();fn();cur=Math.min(cur,a.length-1);render()}; $('dAddB').onclick=()=>{let x=add();if(x)mutate(()=>a.unshift(x))}; $('dAddE').onclick=()=>{let x=add();if(x)mutate(()=>a.push(x))}; $('dAddP').onclick=()=>{let x=add(),p=pos($('dPos').value,a.length+1);if(x&&p)mutate(()=>a.splice(p-1,0,x))}; $('dDelB').onclick=()=>{if(a.length)mutate(()=>a.shift())}; $('dDelE').onclick=()=>{if(a.length)mutate(()=>a.pop())}; $('dDelP').onclick=()=>{let p=pos($('dPos').value,a.length);if(!p)return msg('Enter a valid position.');mutate(()=>a.splice(p-1,1))}; $('dUndo').onclick=()=>{if(hist.length){a=hist.pop();cur=0;render();msg('Last change undone.')}}; $('dReset').onclick=()=>{a=[];hist=[];cur=0;render();msg('Playlist reset. Add music to begin.')}; $('dPlay').onclick=()=>play(cur); $('dPause').onclick=()=>$('dAudio').pause(); $('dPrev').onclick=()=>{if(a.length)play((cur-1+a.length)%a.length)}; $('dNext').onclick=()=>{if(a.length)play((cur+1)%a.length)}; render();}
// CIRCULAR
if($('circularGame')){let a=['Ana','Ben','Carlo','Dana','Ella'],hist=[],cur=0,timer=null,passes=0;const save=()=>hist.push(a.slice());const render=()=>{$('cCircle').innerHTML='';let r=115,n=a.length; a.forEach((v,i)=>{let ang=-Math.PI/2+i*(2*Math.PI/n),x=140+r*Math.cos(ang),y=140+r*Math.sin(ang);let d=document.createElement('div');d.className='player '+(i===cur?'current':'');d.style.left=x+'px';d.style.top=y+'px';d.textContent=v;$('cCircle').appendChild(d)});};const msg=t=>$('cMsg').textContent=t;const mutate=fn=>{save();fn();cur=Math.min(cur,a.length-1);render()};function add(){let n=$('cName').value.trim();if(!n)return msg('Enter a player name.');if(a.includes(n))return msg('That player already exists.');return n}$('cAddB').onclick=()=>{let n=add();if(n)mutate(()=>a.unshift(n))};$('cAddE').onclick=()=>{let n=add();if(n)mutate(()=>a.push(n))};$('cAddP').onclick=()=>{let n=add(),p=pos($('cPos').value,a.length+1);if(n&&p)mutate(()=>a.splice(p-1,0,n))};$('cDelB').onclick=()=>{if(a.length)mutate(()=>a.shift())};$('cDelE').onclick=()=>{if(a.length)mutate(()=>a.pop())};$('cDelP').onclick=()=>{let p=pos($('cPos').value,a.length);if(!p)return msg('Enter a valid position.');mutate(()=>a.splice(p-1,1))};$('cUndo').onclick=()=>{if(hist.length){a=hist.pop();cur=0;render();msg('Last change undone.')}};$('cReset').onclick=()=>{clearInterval(timer);timer=null;a=['Ana','Ben','Carlo','Dana','Ella'];cur=0;passes=0;render();msg('Game reset.')};$('cStart').onclick=()=>{if(a.length<2)return msg('Add at least two players.');clearInterval(timer);passes=0;msg('🥔 Game started! Passing automatically...');timer=setInterval(()=>{if(a.length<2){clearInterval(timer);msg('🏆 Winner: '+a[0]);return}cur=(cur+1)%a.length;passes++;render();if(passes>=5){let out=a[cur];save();a.splice(cur,1);if(cur>=a.length)cur=0;passes=0;render();msg('💥 '+out+' was eliminated!');if(a.length===1){clearInterval(timer);msg('🏆 '+a[0]+' is the winner!')}}},1200)};$('cPause').onclick=()=>{clearInterval(timer);timer=null;msg('Game paused.');};render();}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
})();</script><?php include 'partials/footer.php'; ?></body></html>